  // ✅ 50 جملة - عن العائلة (Family) - الجمل الأصلية + 39 جملة جديدة
  final List<ItemCard> sentences = const [
    // ========== الجمل الأصلية من الصور (11 جملة) ==========
    ItemCard(english: "My toddler niece is so beautiful; I can't stop looking at her and smiling.", translations: {"ar": "بنت أخويا/أختي اللي بتحبني جميلة أوي مش قادر أبطأ أبطأها وأبتسم.", "de": "Meine kleine Nichte ist so schön; ich kann nicht aufhören, sie anzusehen und zu lächeln.", "es": "Mi sobrina pequeña es tan hermosa; no puedo dejar de mirarla y sonreír.", "fr": "Ma petite nièce est si belle; je ne peux pas m'arrêter de la regarder et de sourire.", "it": "Mia nipote piccola è così bella; non riesco a smettere di guardarla e sorridere.", "ru": "Моя маленькая племянница такая красивая; я не могу перестать смотреть на нее и улыбаться.", "zh": "我的小侄女太漂亮了；我忍不住看着她微笑。", "tr": "Küçük yeğenim çok güzel; ona bakıp gülümsemekten kendimi alamıyorum."}),
    ItemCard(english: "People say it's unusual that my paternal aunt likes my mom.", translations: {"ar": "الناس يتقول انه مش مألوف ان عمتي بتحب مامتي.", "de": "Die Leute sagen, es ist ungewöhnlich, dass meine Tante väterlicherseits meine Mutter mag.", "es": "La gente dice que es inusual que mi tía paterna quiera a mi mamá.", "fr": "Les gens disent qu'il est inhabituel que ma tante paternelle aime ma mère.", "it": "La gente dice che sia insolito che mia zia paterna voglia bene a mia mamma.", "ru": "Люди говорят, что необычно, что моя тетя по отцовской линии любит мою маму.", "zh": "人们说我的姑妈喜欢我妈妈很不寻常。", "tr": "İnsanlar babamın kız kardeşinin annemi sevmesinin alışılmadık olduğunu söylüyor."}),
    ItemCard(english: "It feels so special to be the descendants of the Ancient Egyptians.", translations: {"ar": "إحساس مميز جدًا اننا نكون احفاد القدماء المصريين.", "de": "Es fühlt sich so besonders an, die Nachkommen der alten Ägypter zu sein.", "es": "Se siente tan especial ser los descendientes de los antiguos egipcios.", "fr": "C'est tellement spécial d'être les descendants des anciens Égyptiens.", "it": "È così speciale essere i discendenti degli antichi egiziani.", "ru": "Это так особенное чувство - быть потомками древних египтян.", "zh": "作为古埃及人的后裔感觉非常特别。", "tr": "Eski Mısırlıların torunları olmak çok özel bir his."}),
    ItemCard(english: "His wife is so nice; he must be a happy husband.", translations: {"ar": "زوجته لطيفة جدًا، هو أكيد زوج سعيد.", "de": "Seine Frau ist so nett; er muss ein glücklicher Ehemann sein.", "es": "Su esposa es muy agradable; él debe ser un esposo feliz.", "fr": "Sa femme est si gentille; il doit être un mari heureux.", "it": "Sua moglie è così gentile; deve essere un marito felice.", "ru": "Его жена такая милая; он, должно быть, счастливый муж.", "zh": "他的妻子真好；他一定是个快乐的丈夫。", "tr": "Karısı çok nazik; mutlu bir koca olmalı."}),
    ItemCard(english: "She can't be pregnant because she reached her menopause two years ago.", translations: {"ar": "هي مش ممكن تكون حامل عشان هي وصلت لسن اليأس من سنتين.", "de": "Sie kann nicht schwanger sein, weil sie vor zwei Jahren in die Wechseljahre gekommen ist.", "es": "No puede estar embarazada porque llegó a la menopausia hace dos años.", "fr": "Elle ne peut pas être enceinte car elle a atteint la ménopause il y a deux ans.", "it": "Non può essere incinta perché è arrivata alla menopausa due anni fa.", "ru": "Она не может быть беременна, потому что у нее наступила менопауза два года назад.", "zh": "她不可能怀孕，因为她两年前就到了更年期。", "tr": "Hamile olamaz çünkü iki yıl önce menopoza girdi."}),
    ItemCard(english: "My brothers' fiancée is so cute, and I think they're the best couple.", translations: {"ar": "خطيبة أخويا جميلة أوي وأظن إنهم أفضل زوج/ اتنين مرتبطين.", "de": "Die Verlobte meines Bruders ist so süß, und ich denke, sie sind das beste Paar.", "es": "La prometida de mi hermano es tan linda, y creo que son la mejor pareja.", "fr": "La fiancée de mon frère est si mignonne, et je pense qu'ils sont le meilleur couple.", "it": "La fidanzata di mio fratello è così carina, e penso che siano la migliore coppia.", "ru": "Невеста моего брата такая милая, и я думаю, они лучшая пара.", "zh": "我哥哥的未婚妻太可爱了，我认为他们是最好的情侣。", "tr": "Erkek kardeşimin nişanlısı çok tatlı ve bence onlar en iyi çift."}),
    ItemCard(english: "Ali didn't love any woman after his wife's death, he is a sincere widower.", translations: {"ar": "علي ماحبش أي ست من بعد موت زوجته. هو أرمل مخلص.", "de": "Ali liebte nach dem Tod seiner Frau keine andere Frau, er ist ein aufrichtiger Witwer.", "es": "Ali no amó a ninguna mujer después de la muerte de su esposa, es un viudo sincero.", "fr": "Ali n'a aimé aucune femme après la mort de sa femme, c'est un veuf sincère.", "it": "Ali non amò nessuna donna dopo la morte di sua moglie, è un vedovo sincero.", "ru": "Али не любил ни одной женщины после смерти жены, он искренний вдовец.", "zh": "阿里在妻子去世后没有再爱过任何女人，他是一个真诚的鳏夫。", "tr": "Ali karısının ölümünden sonra hiçbir kadını sevmedi, samimi bir dul erkek."}),
    ItemCard(english: "Do you know that King Lear had three daughters and no sons?", translations: {"ar": "انت عارف ان الملك لير كان عنده 3 بنات ومعندوش وال ابن؟", "de": "Weißt du, dass König Lear drei Töchter und keine Söhne hatte?", "es": "¿Sabes que el Rey Lear tenía tres hijas y ningún hijo?", "fr": "Savez-vous que le roi Lear avait trois filles et aucun fils?", "it": "Sai che Re Lear aveva tre figlie e nessun figlio maschio?", "ru": "Знаете ли вы, что у короля Лира было три дочери и ни одного сына?", "zh": "你知道李尔王有三个女儿而没有儿子吗？", "tr": "Kral Lear'ın üç kızı olduğunu ve hiç oğlu olmadığını biliyor musun?"}),
    ItemCard(english: "His mother-in-law has been ill since his father-in-law died.", translations: {"ar": "حماته تعبئة من وقت ما حماه اتوفى.", "de": "Seiner Schwiegermutter geht es schlecht, seit sein Schwiegervater gestorben ist.", "es": "Su suegra ha estado enferma desde que murió su suegro.", "fr": "Sa belle-mère est malade depuis que son beau-père est mort.", "it": "Sua suocera è malata da quando è morto suo suocero.", "ru": "Его теща болеет с тех пор, как умер его тесть.", "zh": "自从他的岳父去世后，他的岳母就一直生病。", "tr": "Kayınpederi öldüğünden beri kayınvalidesi hasta."}),
    ItemCard(english: "Don't listen to him; he is a senile man.", translations: {"ar": "ما تسمعش كلامه ده راجل كبر وخرف.", "de": "Hör nicht auf ihn; er ist ein seniler Mann.", "es": "No lo escuches; es un hombre senil.", "fr": "Ne l'écoute pas; c'est un homme sénile.", "it": "Non ascoltarlo; è un uomo senile.", "ru": "Не слушай его; он старый и слабоумный.", "zh": "别听他的；他是个老糊涂的人。", "tr": "Onu dinleme; o bunak bir adam."}),
    ItemCard(english: "Her parents were divorced long time ago, so she lives with her mother and her step-dad.", translations: {"ar": "باباها ومامتها انطلقوا من وقت طويل عشان كده هي عايشة مع مامتها وجوز مامتها.", "de": "Ihre Eltern wurden vor langer Zeit geschieden, also lebt sie mit ihrer Mutter und ihrem Stiefvater.", "es": "Sus padres se divorciaron hace mucho tiempo, así que vive con su madre y su padrastro.", "fr": "Ses parents ont divorcé il y a longtemps, alors elle vit avec sa mère et son beau-père.", "it": "I suoi genitori hanno divorziato molto tempo fa, quindi vive con sua madre e il suo patrigno.", "ru": "Ее родители развелись давно, поэтому она живет с матерью и отчимом.", "zh": "她的父母很久以前就离婚了，所以她和她的母亲和继父住在一起。", "tr": "Anne babası uzun zaman önce boşandı, bu yüzden annesi ve üvey babasıyla yaşıyor."}),
    
    // ========== 39 جملة إضافية لتكمل 50 جملة ==========
    ItemCard(english: "My father is the best man I know.", translations: {"ar": "والدي هو أفضل رجل أعرفه.", "de": "Mein Vater ist der beste Mann, den ich kenne.", "es": "Mi padre es el mejor hombre que conozco.", "fr": "Mon père est le meilleur homme que je connaisse.", "it": "Mio padre è il miglior uomo che conosca.", "ru": "Мой отец - лучший мужчина, которого я знаю.", "zh": "我的父亲是我认识的最好的人。", "tr": "Babam tanıdığım en iyi adamdır."}),
    ItemCard(english: "My mother cooks delicious food every day.", translations: {"ar": "أمي تطبخ طعام لذيذ كل يوم.", "de": "Meine Mutter kocht jeden Tag köstliches Essen.", "es": "Mi madre cocina comida deliciosa todos los días.", "fr": "Ma mère cuisine des plats délicieux tous les jours.", "it": "Mia madre cucina cibo delizioso ogni giorno.", "ru": "Моя мама каждый день готовит вкусную еду.", "zh": "我妈妈每天做美味的食物。", "tr": "Annem her gün lezzetli yemekler pişirir."}),
    ItemCard(english: "I have two brothers and one sister.", translations: {"ar": "لدي أخوان وأخت واحدة.", "de": "Ich habe zwei Brüder und eine Schwester.", "es": "Tengo dos hermanos y una hermana.", "fr": "J'ai deux frères et une sœur.", "it": "Ho due fratelli e una sorella.", "ru": "У меня два брата и одна сестра.", "zh": "我有两个兄弟和一个姐妹。", "tr": "İki erkek kardeşim ve bir kız kardeşim var."}),
    ItemCard(english: "My grandfather tells me stories about his childhood.", translations: {"ar": "جدي يخبرني قصص عن طفولته.", "de": "Mein Großvater erzählt mir Geschichten aus seiner Kindheit.", "es": "Mi abuelo me cuenta historias de su infancia.", "fr": "Mon grand-père me raconte des histoires de son enfance.", "it": "Mio nonno mi racconta storie della sua infanzia.", "ru": "Мой дедушка рассказывает мне истории о своем детстве.", "zh": "我的祖父给我讲他童年的故事。", "tr": "Büyükbabam bana çocukluğuyla ilgili hikayeler anlatır."}),
    ItemCard(english: "My grandmother knits sweaters for the whole family.", translations: {"ar": "جدتي تحيك كنزات للعائلة كلها.", "de": "Meine Großmutter strickt Pullover für die ganze Familie.", "es": "Mi abuela teje suéteres para toda la familia.", "fr": "Ma grand-mère tricote des pulls pour toute la famille.", "it": "Mia nonna lavora a maglia maglioni per tutta la famiglia.", "ru": "Моя бабушка вяжет свитера для всей семьи.", "zh": "我的祖母给全家人织毛衣。", "tr": "Büyükannem tüm aile için kazaklar örüyor."}),
    ItemCard(english: "My uncle is a pilot and travels around the world.", translations: {"ar": "عمي طيار ويسافر حول العالم.", "de": "Mein Onkel ist Pilot und reist um die Welt.", "es": "Mi tío es piloto y viaja por todo el mundo.", "fr": "Mon oncle est pilote et voyage dans le monde entier.", "it": "Mio zio è un pilota e viaggia per il mondo.", "ru": "Мой дядя - пилот и путешествует по миру.", "zh": "我的叔叔是一名飞行员，环游世界。", "tr": "Amcam bir pilottur ve dünyayı dolaşır."}),
    ItemCard(english: "My aunt is a doctor and she helps many people.", translations: {"ar": "عمتي طبيبة وتساعد الكثير من الناس.", "de": "Meine Tante ist Ärztin und hilft vielen Menschen.", "es": "Mi tía es médica y ayuda a muchas personas.", "fr": "Ma tante est médecin et elle aide beaucoup de gens.", "it": "Mia zia è un medico e aiuta molte persone.", "ru": "Моя тетя - врач и помогает многим людям.", "zh": "我的阿姨是一名医生，她帮助很多人。", "tr": "Teyzem bir doktordur ve birçok insana yardım eder."}),
    ItemCard(english: "I am the eldest child in my family.", translations: {"ar": "أنا أكبر طفل في عائلتي.", "de": "Ich bin das älteste Kind in meiner Familie.", "es": "Soy el hijo mayor de mi familia.", "fr": "Je suis l'aîné de ma famille.", "it": "Sono il figlio più grande della mia famiglia.", "ru": "Я старший ребенок в семье.", "zh": "我是家里最大的孩子。", "tr": "Ailemin en büyük çocuğuyum."}),
    ItemCard(english: "My little sister is very annoying but I love her.", translations: {"ar": "أختي الصغيرة مزعجة جدًا لكني أحبها.", "de": "Meine kleine Schwester ist sehr nervig, aber ich liebe sie.", "es": "Mi hermana pequeña es muy molesta pero la quiero.", "fr": "Ma petite sœur est très agaçante mais je l'aime.", "it": "La mia sorellina è molto fastidiosa ma la amo.", "ru": "Моя младшая сестра очень надоедливая, но я люблю её.", "zh": "我的小妹妹很烦人，但我爱她。", "tr": "Küçük kız kardeşim çok sinir bozucu ama onu seviyorum."}),
    ItemCard(english: "We are having a family reunion next month.", translations: {"ar": "لدينا لم شمل عائلي الشهر القادم.", "de": "Wir haben nächsten Monat ein Familientreffen.", "es": "Tendremos una reunión familiar el próximo mes.", "fr": "Nous avons une réunion de famille le mois prochain.", "it": "Abbiamo una riunione di famiglia il mese prossimo.", "ru": "У нас семейная встреча в следующем месяце.", "zh": "下个月我们有家庭聚会。", "tr": "Gelecek ay aile toplantımız var."}),
    ItemCard(english: "My cousin is getting married next week.", translations: {"ar": "ابن عمي سيتزوج الأسبوع القادم.", "de": "Mein Cousin heiratet nächste Woche.", "es": "Mi primo se casa la semana que viene.", "fr": "Mon cousin se marie la semaine prochaine.", "it": "Mio cugino si sposa la prossima settimana.", "ru": "Мой двоюродный брат женится на следующей неделе.", "zh": "我的表弟下周结婚。", "tr": "Kuzenim haftaya evleniyor."}),
    ItemCard(english: "She is pregnant with her first baby.", translations: {"ar": "هي حامل في أول طفل لها.", "de": "Sie ist mit ihrem ersten Baby schwanger.", "es": "Está embarazada de su primer bebé.", "fr": "Elle est enceinte de son premier bébé.", "it": "È incinta del suo primo bambino.", "ru": "Она беременна своим первым ребенком.", "zh": "她怀了第一个孩子。", "tr": "İlk bebeğine hamile."}),
    ItemCard(english: "The baby is only three months old.", translations: {"ar": "الطفل عمره ثلاثة أشهر فقط.", "de": "Das Baby ist erst drei Monate alt.", "es": "El bebé tiene solo tres meses.", "fr": "Le bébé n'a que trois mois.", "it": "Il bambino ha solo tre mesi.", "ru": "Ребенку всего три месяца.", "zh": "婴儿只有三个月大。", "tr": "Bebek sadece üç aylık."}),
    ItemCard(english: "My step-mother is very kind to me.", translations: {"ar": "زوجة أبي لطيفة جدًا معي.", "de": "Meine Stiefmutter ist sehr nett zu mir.", "es": "Mi madrastra es muy amable conmigo.", "fr": "Ma belle-mère est très gentille avec moi.", "it": "La mia matrigna è molto gentile con me.", "ru": "Моя мачеха очень добра ко мне.", "zh": "我的继母对我很好。", "tr": "Üvey annem bana çok nazik."}),
    ItemCard(english: "After the divorce, she lives with her step-father.", translations: {"ar": "بعد الطلاق، تعيش مع زوج أمها.", "de": "Nach der Scheidung lebt sie mit ihrem Stiefvater.", "es": "Después del divorcio, vive con su padrastro.", "fr": "Après le divorce, elle vit avec son beau-père.", "it": "Dopo il divorzio, vive con il suo patrigno.", "ru": "После развода она живет с отчимом.", "zh": "离婚后，她和继父住在一起。", "tr": "Boşanmadan sonra üvey babasıyla yaşıyor."}),
    ItemCard(english: "They have been married for twenty years.", translations: {"ar": "لقد تزوجا منذ عشرين عامًا.", "de": "Sie sind seit zwanzig Jahren verheiratet.", "es": "Han estado casados durante veinte años.", "fr": "Ils sont mariés depuis vingt ans.", "it": "Sono sposati da vent'anni.", "ru": "Они женаты уже двадцать лет.", "zh": "他们已经结婚二十年了。", "tr": "Yirmi yıldır evliler."}),
    ItemCard(english: "He is a widower raising three children alone.", translations: {"ar": "هو أرمل يربي ثلاثة أطفال بمفرده.", "de": "Er ist ein Witwer, der drei Kinder alleine großzieht.", "es": "Es viudo y cría a tres hijos solo.", "fr": "C'est un veuf qui élève trois enfants seul.", "it": "È un vedovo che alleva tre figli da solo.", "ru": "Он вдовец, воспитывающий троих детей в одиночку.", "zh": "他是一个鳏夫，独自抚养三个孩子。", "tr": "Üç çocuğu tek başına büyüten bir dul erkek."}),
    ItemCard(english: "She became a widow at a young age.", translations: {"ar": "أصبحت أرملة في سن مبكرة.", "de": "Sie wurde in jungen Jahren Witwe.", "es": "Se quedó viuda a una edad temprana.", "fr": "Elle est devenue veuve à un jeune âge.", "it": "È diventata vedova in giovane età.", "ru": "Она стала вдовой в молодом возрасте.", "zh": "她年纪轻轻就成了寡妇。", "tr": "Genç yaşta dul kaldı."}),
    ItemCard(english: "My daughter is learning to play the piano.", translations: {"ar": "ابنتي تتعلم العزف على البيانو.", "de": "Meine Tochter lernt Klavier spielen.", "es": "Mi hija está aprendiendo a tocar el piano.", "fr": "Ma fille apprend à jouer du piano.", "it": "Mia figlia sta imparando a suonare il pianoforte.", "ru": "Моя дочь учится играть на пианино.", "zh": "我女儿正在学弹钢琴。", "tr": "Kızım piyano çalmayı öğreniyor."}),
    ItemCard(english: "My son wants to be a doctor when he grows up.", translations: {"ar": "ابني يريد أن يكون طبيباً عندما يكبر.", "de": "Mein Sohn möchte Arzt werden, wenn er groß ist.", "es": "Mi hijo quiere ser médico cuando sea grande.", "fr": "Mon fils veut être médecin quand il sera grand.", "it": "Mio figlio vuole fare il medico quando sarà grande.", "ru": "Мой сын хочет стать врачом, когда вырастет.", "zh": "我儿子长大后想当医生。", "tr": "Oğlum büyüdüğünde doktor olmak istiyor."}),
    ItemCard(english: "My siblings and I are very close.", translations: {"ar": "أنا وأشقائي قريبون جدًا من بعضنا.", "de": "Meine Geschwister und ich sind uns sehr nahe.", "es": "Mis hermanos y yo somos muy unidos.", "fr": "Mes frères et sœurs et moi sommes très proches.", "it": "Io e i miei fratelli siamo molto legati.", "ru": "Мы с братьями и сестрами очень близки.", "zh": "我和我的兄弟姐妹们非常亲密。", "tr": "Kardeşlerim ve ben birbirimize çok yakınız."}),
    ItemCard(english: "Family is the most important thing in life.", translations: {"ar": "العائلة هي أهم شيء في الحياة.", "de": "Familie ist das Wichtigste im Leben.", "es": "La familia es lo más importante en la vida.", "fr": "La famille est la chose la plus importante dans la vie.", "it": "La famiglia è la cosa più importante nella vita.", "ru": "Семья - это самое важное в жизни.", "zh": "家庭是生活中最重要的事情。", "tr": "Aile hayattaki en önemli şeydir."}),
    ItemCard(english: "My parents always support me.", translations: {"ar": "والداي دائمًا يدعماني.", "de": "Meine Eltern unterstützen mich immer.", "es": "Mis padres siempre me apoyan.", "fr": "Mes parents me soutiennent toujours.", "it": "I miei genitori mi supportano sempre.", "ru": "Мои родители всегда поддерживают меня.", "zh": "我的父母总是支持我。", "tr": "Ailem beni her zaman destekler."}),
    ItemCard(english: "We are a family of five.", translations: {"ar": "نحن عائلة من خمسة أفراد.", "de": "Wir sind eine fünfköpfige Familie.", "es": "Somos una familia de cinco.", "fr": "Nous sommes une famille de cinq.", "it": "Siamo una famiglia di cinque persone.", "ru": "Нас в семье пятеро.", "zh": "我们是一家五口。", "tr": "Beş kişilik bir aileyiz."}),
    ItemCard(english: "My grandfather passed away last year.", translations: {"ar": "توفي جدي العام الماضي.", "de": "Mein Großvater ist letztes Jahr gestorben.", "es": "Mi abuelo falleció el año pasado.", "fr": "Mon grand-père est décédé l'année dernière.", "it": "Mio nonno è morto l'anno scorso.", "ru": "Мой дедушка скончался в прошлом году.", "zh": "我的祖父去年去世了。", "tr": "Büyükbabam geçen yıl vefat etti."}),
    ItemCard(english: "We are expecting a new member in the family.", translations: {"ar": "ننتظر فردًا جديدًا في العائلة.", "de": "Wir erwarten ein neues Familienmitglied.", "es": "Esperamos un nuevo miembro en la familia.", "fr": "Nous attendons un nouveau membre dans la famille.", "it": "Aspettiamo un nuovo membro della famiglia.", "ru": "Мы ждем нового члена семьи.", "zh": "我们期待家庭中有新成员。", "tr": "Ailede yeni bir üye bekliyoruz."}),
    ItemCard(english: "My daughter-in-law is very helpful.", translations: {"ar": "زوجة ابني مفيدة جدًا.", "de": "Meine Schwiegertochter ist sehr hilfreich.", "es": "Mi nuera es muy servicial.", "fr": "Ma belle-fille est très serviable.", "it": "Mia nuora è molto disponibile.", "ru": "Моя невестка очень отзывчивая.", "zh": "我的儿媳很乐于助人。", "tr": "Gelinim çok yardımsever."}),
    ItemCard(english: "My son-in-law is a lawyer.", translations: {"ar": "زوج ابنتي محام.", "de": "Mein Schwiegersohn ist Anwalt.", "es": "Mi yerno es abogado.", "fr": "Mon gendre est avocat.", "it": "Mio genero è un avvocato.", "ru": "Мой зять - адвокат.", "zh": "我的女婿是一名律师。", "tr": "Damadım bir avukattır."}),
    ItemCard(english: "My ancestors came from Egypt.", translations: {"ar": "أسلافي جاءوا من مصر.", "de": "Meine Vorfahren kamen aus Ägypten.", "es": "Mis antepasados vinieron de Egipto.", "fr": "Mes ancêtres venaient d'Égypte.", "it": "I miei antenati venivano dall'Egitto.", "ru": "Мои предки приехали из Египта.", "zh": "我的祖先来自埃及。", "tr": "Atalarım Mısır'dan geldi."}),
    ItemCard(english: "The twins look exactly like their mother.", translations: {"ar": "التوأمان يشبهان أمهما تمامًا.", "de": "Die Zwillinge sehen genau wie ihre Mutter aus.", "es": "Los mellizos se parecen exactamente a su madre.", "fr": "Les jumeaux ressemblent exactement à leur mère.", "it": "I gemelli assomigliano esattamente alla loro madre.", "ru": "Близнецы выглядят точно как их мать.", "zh": "双胞胎长得完全像他们的母亲。", "tr": "İkizler tıpkı annelerine benziyor."}),
    ItemCard(english: "He is an only child and feels lonely sometimes.", translations: {"ar": "هو طفل وحيد ويشعر بالوحدة أحيانًا.", "de": "Er ist ein Einzelkind und fühlt sich manchmal einsam.", "es": "Es hijo único y a veces se siente solo.", "fr": "C'est un enfant unique et il se sent parfois seul.", "it": "È figlio unico e a volte si sente solo.", "ru": "Он единственный ребенок и иногда чувствует себя одиноким.", "zh": "他是独生子，有时感到孤独。", "tr": "Tek çocuk ve bazen yalnız hissediyor."}),
    ItemCard(english: "The orphan was adopted by a kind family.", translations: {"ar": "تم تبنى اليتيم من قبل عائلة طيبة.", "de": "Die Waise wurde von einer freundlichen Familie adoptiert.", "es": "El huérfano fue adoptado por una familia amable.", "fr": "L'orphelin a été adopté par une famille gentille.", "it": "L'orfano è stato adottato da una famiglia gentile.", "ru": "Сирота был усыновлен доброй семьей.", "zh": "这个孤儿被一个好心的家庭收养了。", "tr": "Yetim, nazik bir aile tarafından evlat edinildi."}),
    ItemCard(english: "My godfather gives me the best advice.", translations: {"ar": "عرابي يعطيني أفضل النصائح.", "de": "Mein Pate gibt mir die besten Ratschläge.", "es": "Mi padrino me da los mejores consejos.", "fr": "Mon parrain me donne les meilleurs conseils.", "it": "Il mio padrino mi dà i migliori consigli.", "ru": "Мой крестный отец дает мне лучшие советы.", "zh": "我的教父给了我最好的建议。", "tr": "Vaftiz babam bana en iyi tavsiyeleri veriyor."}),
    ItemCard(english: "She is my closest relative.", translations: {"ar": "هي أقرب قريباتي.", "de": "Sie ist mein nächster Verwandter.", "es": "Ella es mi pariente más cercana.", "fr": "Elle est ma plus proche parente.", "it": "Lei è la mia parente più stretta.", "ru": "Она мой самый близкий родственник.", "zh": "她是我最亲近的亲戚。", "tr": "O benim en yakın akrabam."}),
    ItemCard(english: "Family comes first, always.", translations: {"ar": "العائلة أولاً، دائمًا.", "de": "Familie kommt immer zuerst.", "es": "La familia es lo primero, siempre.", "fr": "La famille passe avant tout, toujours.", "it": "La famiglia viene prima, sempre.", "ru": "Семья всегда на первом месте.", "zh": "家庭永远第一。", "tr": "Aile her zaman birinci gelir."}),
    ItemCard(english: "My brother is my best friend.", translations: {"ar": "أخي هو أفضل صديق لي.", "de": "Mein Bruder ist mein bester Freund.", "es": "Mi hermano es mi mejor amigo.", "fr": "Mon frère est mon meilleur ami.", "it": "Mio fratello è il mio migliore amico.", "ru": "Мой брат - мой лучший друг.", "zh": "我的兄弟是我最好的朋友。", "tr": "Erkek kardeşim en iyi arkadaşımdır."}),
    ItemCard(english: "My sister is getting married next summer.", translations: {"ar": "أختي ستتزوج الصيف القادم.", "de": "Meine Schwester heiratet nächsten Sommer.", "es": "Mi hermana se casa el próximo verano.", "fr": "Ma sœur se marie l'été prochain.", "it": "Mia sorella si sposa la prossima estate.", "ru": "Моя сестра выходит замуж следующим летом.", "zh": "我妹妹明年夏天结婚。", "tr": "Kız kardeşim gelecek yaz evleniyor."}),
    ItemCard(english: "My grandparents live in a small village.", translations: {"ar": "أجدادي يعيشون في قرية صغيرة.", "de": "Meine Großeltern leben in einem kleinen Dorf.", "es": "Mis abuelos viven en un pequeño pueblo.", "fr": "Mes grands-parents vivent dans un petit village.", "it": "I miei nonni vivono in un piccolo villaggio.", "ru": "Мои бабушка и дедушка живут в маленькой деревне.", "zh": "我的祖父母住在一个小村庄里。", "tr": "Büyükannem ve büyükbabam küçük bir köyde yaşıyor."}),
    ItemCard(english: "I miss my family when I'm away.", translations: {"ar": "أشتاق لعائلتي عندما أكون بعيدًا.", "de": "Ich vermisse meine Familie, wenn ich weg bin.", "es": "Extraño a mi familia cuando estoy lejos.", "fr": "Ma famille me manque quand je suis loin.", "it": "La mia famiglia mi manca quando sono via.", "ru": "Я скучаю по своей семье, когда меня нет рядом.", "zh": "当我不在时，我想念我的家人。", "tr": "Uzaktayken ailemi özlüyorum."}),
    ItemCard(english: "My nephew is very smart for his age.", translations: {"ar": "ابن أخي ذكي جدًا لعمره.", "de": "Mein Neffe ist sehr klug für sein Alter.", "es": "Mi sobrino es muy inteligente para su edad.", "fr": "Mon neveu est très intelligent pour son âge.", "it": "Mio nipote è molto intelligente per la sua età.", "ru": "Мой племянник очень умный для своего возраста.", "zh": "我的侄子在他这个年纪非常聪明。", "tr": "Yeğenim yaşına göre çok zeki."}),
    ItemCard(english: "My niece loves to dance.", translations: {"ar": "ابنة أخي تحب الرقص.", "de": "Meine Nichte liebt es zu tanzen.", "es": "Mi sobrina ama bailar.", "fr": "Ma nièce adore danser.", "it": "Mia nipote ama ballare.", "ru": "Моя племянница любит танцевать.", "zh": "我的侄女喜欢跳舞。", "tr": "Yeğenim dans etmeyi çok sever."}),
    ItemCard(english: "We are related by marriage.", translations: {"ar": "نحن مرتبطون عن طريق الزواج.", "de": "Wir sind durch Heirat verwandt.", "es": "Estamos emparentados por matrimonio.", "fr": "Nous sommes apparentés par mariage.", "it": "Siamo imparentati per matrimonio.", "ru": "Мы связаны браком.", "zh": "我们通过婚姻联系在一起。", "tr": "Evlilik yoluyla akrabayız."}),
    ItemCard(english: "My mother-in-law is visiting us this weekend.", translations: {"ar": "حماتي تزورنا نهاية هذا الأسبوع.", "de": "Meine Schwiegermutter besucht uns dieses Wochenende.", "es": "Mi suegra nos visita este fin de semana.", "fr": "Ma belle-mère nous rend visite ce week-end.", "it": "Mia suocera ci visita questo fine settimana.", "ru": "Моя теща навещает нас на этих выходных.", "zh": "我的岳母这个周末来看我们。", "tr": "Kayınvalidem bu hafta sonu bizi ziyaret ediyor."}),
    ItemCard(english: "My father-in-law is retired now.", translations: {"ar": "حموي متقاعد الآن.", "de": "Mein Schwiegervater ist jetzt im Ruhestand.", "es": "Mi suegro está jubilado ahora.", "fr": "Mon beau-père est maintenant à la retraite.", "it": "Mio suocero è ora in pensione.", "ru": "Мой тесть сейчас на пенсии.", "zh": "我的岳父现在退休了。", "tr": "Kayınpederim şimdi emekli."}),
    ItemCard(english: "Blood is thicker than water.", translations: {"ar": "الدم أغلى من الماء.", "de": "Blut ist dicker als Wasser.", "es": "La sangre es más espesa que el agua.", "fr": "Le sang est plus épais que l'eau.", "it": "Il sangue è più denso dell'acqua.", "ru": "Кровь гуще воды.", "zh": "血浓于水。", "tr": "Kan su'dan yoğundur."}),
  ];

