    ItemCard(english: "She does yoga every morning.", translations: {"ar": "هي بتعمل يوجا كل صباح", "de": "Sie macht jeden Morgen Yoga", "es": "Ella hace yoga todas las mañanas", "fr": "Elle fait du yoga tous les matins", "it": "Fa yoga ogni mattina", "ru": "Она занимается йогой каждое утро", "zh": "她每天早上做瑜伽", "tr": "Her sabah yoga yapar"}),
