    ItemCard(english: "The treadmill is great for cardio.", translations: {"ar": "المشاية ممتازة للكارديو", "de": "Das Laufband ist großartig für Cardio", "es": "La cinta de correr es excelente para cardio", "fr": "Le tapis roulant est idéal pour le cardio", "it": "Il tapis roulant è ottimo per il cardio", "ru": "Беговая дорожка отлично подходит для кардио", "zh": "跑步机非常适合有氧运动", "tr": "Koşu bandı kardiyo için harikadır"}),
    ItemCard(english: "He has huge biceps from all that lifting.", translations: {"ar": "عنده باي ضخم من كل الرفع ده", "de": "Er hat riesige Bizeps von all dem Heben", "es": "Tiene bíceps enormes de todo ese levantamiento", "fr": "Il a d'énormes biceps à force de soulever", "it": "Ha bicipiti enormi da tutto quel sollevamento", "ru": "У него огромные бицепсы от всех этих подъемов", "zh": "举重练出了巨大的二头肌", "tr": "Tüm bu kaldırmalardan kocaman pazıları var"}),
    ItemCard(english: "Remember to stretch after exercising.", translations: {"ar": "إفتكر تعمل إطالة بعد التمرين", "de": "Denken Sie daran, sich nach dem Training zu dehnen", "es": "Recuerda estirarte después de hacer ejercicio", "fr": "N'oubliez pas de vous étirer après l'exercice", "it": "Ricordati di allungarti dopo l'esercizio", "ru": "Не забывайте растягиваться после тренировки", "zh": "运动后记得拉伸", "tr": "Egzersizden sonra esnemeyi unutmayın"}),
    ItemCard(english: "He takes protein shakes to help muscle recovery.", translations: {"ar": "هو بياخد مخفوق بروتين عشان يساعد في استشفاء العضلات", "de": "Er nimmt Proteinshakes, um die Muskelregeneration zu unterstützen", "es": "Toma batidos de proteínas para ayudar a la recuperación muscular", "fr": "Il prend des shakes protéinés pour aider à la récupération musculaire", "it": "Prende frullati proteici per aiutare il recupero muscolare", "ru": "Он принимает протеиновые коктейли для восстановления мышц", "zh": "他喝蛋白奶昔帮助肌肉恢复", "tr": "Kas iyileşmesine yardımcı olması için protein shake içiyor"}),
    ItemCard(english: "The punching bag is used for boxing training.", translations: {"ar": "كيس الملاكمة بيتستخدم لتدريب الملاكمة", "de": "Der Boxsack wird für das Boxtraining verwendet", "es": "El saco de boxeo se usa para entrenar boxeo", "fr": "Le sac de frappe est utilisé pour l'entraînement de boxe", "it": "Il sacco da boxe viene utilizzato per l'addestramento alla boxe", "ru": "Боксерская груша используется для тренировок по боксу", "zh": "沙袋用于拳击训练", "tr": "Boks torbası boks eğitimi için kullanılır"}),
    ItemCard(english: "Squats are great for building leg strength.", translations: {"ar": "الإسكوات مفيدة جدا لتقوية الرجل", "de": "Kniebeugen sind großartig für den Aufbau von Beinkraft", "es": "Las sentadillas son excelentes para desarrollar fuerza en las piernas", "fr": "Les squats sont excellents pour développer la force des jambes", "it": "Gli squat sono ottimi per sviluppare la forza delle gambe", "ru": "Приседания отлично подходят для укрепления ног", "zh": "深蹲对增强腿部力量很有帮助", "tr": "Squatlar bacak gücü oluşturmak için harikadır"}),
    ItemCard(english: "The sauna helps me relax after working out.", translations: {"ar": "السونا بتساعدني ارتاح بعد التمرين", "de": "Die Sauna hilft mir, mich nach dem Training zu entspannen", "es": "La sauna me ayuda a relajarme después de hacer ejercicio", "fr": "Le sauna m'aide à me détendre après l'entraînement", "it": "La sauna mi aiuta a rilassarmi dopo l'allenamento", "ru": "Сауна помогает мне расслабиться после тренировки", "zh": "桑拿帮助我在锻炼后放松", "tr": "Sauna antrenmandan sonra rahatlamama yardımcı oluyor"}),
    ItemCard(english: "He is training for a bodybuilding competition.", translations: {"ar": "هو بيتدرب لمسابقة كمال أجسام", "de": "Er trainiert für einen Bodybuilding-Wettbewerb", "es": "Está entrenando para una competencia de culturismo", "fr": "Il s'entraîne pour un concours de culturisme", "it": "Si sta allenando per una competizione di bodybuilding", "ru": "Он тренируется для соревнований по бодибилдингу", "zh": "他正在为健美比赛训练", "tr": "Vücut geliştirme yarışması için antrenman yapıyor"}),
    ItemCard(english: "Cardio exercises improve heart health.", translations: {"ar": "تمارين الكارديو بتحسن صحة القلب", "de": "Cardio-Übungen verbessern die Herzgesundheit", "es": "Los ejercicios cardiovasculares mejoran la salud del corazón", "fr": "Les exercices cardio améliorent la santé cardiaque", "it": "Gli esercizi cardio migliorano la salute del cuore", "ru": "Кардио упражнения улучшают здоровье сердца", "zh": "有氧运动改善心脏健康", "tr": "Kardiyo egzersizleri kalp sağlığını iyileştirir"}),
    ItemCard(english: "She is very agile and quick on her feet.", translations: {"ar": "هي رشيقة جدا وسريعة على رجليها", "de": "Sie ist sehr agil und schnell auf den Beinen", "es": "Ella es muy ágil y rápida de pies", "fr": "Elle est très agile et rapide sur ses pieds", "it": "È molto agile e veloce sui piedi", "ru": "Она очень ловкая и быстрая на ногах", "zh": "她非常敏捷，脚步很快", "tr": "Çok çevik ve ayakları üzerinde hızlı"}),
    ItemCard(english: "Using steroids can be dangerous for your health.", translations: {"ar": "إستخدام المنشطات ممكن يكون خطر على صحتك", "de": "Die Verwendung von Steroiden kann gefährlich für Ihre Gesundheit sein", "es": "Usar esteroides puede ser peligroso para tu salud", "fr": "L'utilisation de stéroïdes peut être dangereuse pour votre santé", "it": "L'uso di steroidi può essere pericoloso per la salute", "ru": "Использование стероидов может быть опасным для здоровья", "zh": "使用类固醇可能对健康有害", "tr": "Steroid kullanmak sağlığınız için tehlikeli olabilir"}),
