    ItemCard(english: "Monkeys live on trees.", translations: {"ar": "القرود بتمشي على الشجر", "de": "Affen leben auf Bäumen", "es": "Los monos viven en los árboles", "fr": "Les singes vivent dans les arbres", "it": "Le scimmie vivono sugli alberi", "ru": "Обезьяны живут на деревьях", "zh": "猴子生活在树上", "tr": "Maymunlar ağaçlarda yaşar"}),
